package com.xyz.question_bank_management_system.modules.learning.controller;
import com.xyz.question_bank_management_system.common.ApiResponse;import com.xyz.question_bank_management_system.modules.learning.dto.ResourceInteractionSubmitRequest;import com.xyz.question_bank_management_system.modules.learning.service.InteractionSubmissionService;import com.xyz.question_bank_management_system.util.SecurityContextUtil;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/v1/resource-interactions") @RequiredArgsConstructor @PreAuthorize("hasRole('STUDENT')") public class ResourceInteractionController {private final InteractionSubmissionService service;@PostMapping public ApiResponse<Map<String,Object>> submit(@RequestHeader("Idempotency-Key")String key,@RequestBody ResourceInteractionSubmitRequest request){return ApiResponse.ok(service.submit(SecurityContextUtil.getUserId(),key,request));}@GetMapping("/{interactionCode}/result") public ApiResponse<Map<String,Object>> result(@PathVariable String interactionCode){return ApiResponse.ok(service.result(SecurityContextUtil.getUserId(),interactionCode));}}
